package io.tornado.optimization;
import io.tornado.api.ReportService;import io.tornado.datafetch.BinanceMarketDataClient;import io.tornado.persistence.*;import io.tornado.strategies.*;import org.slf4j.*;import org.springframework.stereotype.Service;import org.ta4j.core.BarSeries;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class ProfileResearchService{private static final Logger log=LoggerFactory.getLogger(ProfileResearchService.class);private static final int WARMUP_BARS=80;private final BinanceMarketDataClient market;private final CoinRepository coins;private final AppSettingsRepository settings;private final ProfileSelectionService selection;private final WalkForwardProfileSelector selector=new WalkForwardProfileSelector();public ProfileResearchService(BinanceMarketDataClient m,CoinRepository c,AppSettingsRepository s,ProfileSelectionService selection){market=m;coins=c;settings=s;this.selection=selection;}
 public ResearchResult research(ProfileScope scope,String coinSymbol,String strategyCode,long horizon,Instant from,Instant to){ReportService.requireSupportedHorizon(horizon);StrategyDefinition strategy=StrategyDefinition.valueOf(strategyCode);List<Coin>universe;if(scope==ProfileScope.COIN_SPECIFIC){if(coinSymbol==null||coinSymbol.isBlank())throw new IllegalArgumentException("coin is required for a coin-specific profile");universe=List.of(coins.findBySymbolIgnoreCase(coinSymbol).orElseThrow());}else universe=coins.findAllByActiveTrueOrderBySymbol();if(universe.isEmpty())throw new IllegalStateException("No active coins are available for research");if(from==null)from=to.minus(horizon<=3600?Duration.ofDays(90):Duration.ofDays(365));if(!to.isAfter(from))throw new IllegalArgumentException("research end must follow start");AppSettings configuration=settings.findById(1).orElseThrow();Map<WalkForwardProfileSelector.Configuration,List<WalkForwardProfileSelector.Observation>>data=new LinkedHashMap<>();List<String>errors=new ArrayList<>();for(String timeframe:StrategyProfilePolicy.candidateTimeframes(horizon)){Duration warmup=StrategyProfilePolicy.duration(timeframe).multipliedBy(WARMUP_BARS);for(Coin coin:universe)try{BarSeries series=market.historicalCandles(coin.getPair(),timeframe,from.minus(warmup),to);for(String parameters:strategy.parameterKeys()){var key=new WalkForwardProfileSelector.Configuration(timeframe,parameters);data.computeIfAbsent(key,x->new ArrayList<>()).addAll(observations(coin,strategy,parameters,horizon,from,to,series));}}catch(Exception e){errors.add(coin.getSymbol()+"/"+timeframe+": "+e.getMessage());log.warn("Profile research skipped {} {}: {}",coin.getPair(),timeframe,e.getMessage());}}int minimum=scope==ProfileScope.GLOBAL?configuration.getMinimumConfigurationSamples():configuration.getCoinProfileMinimumSamples();List<WalkForwardProfileSelector.CandidateEvaluation>ranked=selector.rank(data,minimum,configuration.getProfileResearchRoundTripCostPercent().doubleValue());var winner=ranked.stream().filter(WalkForwardProfileSelector.CandidateEvaluation::eligible).findFirst().orElse(null);ProfileSelectionService.Selection applied=winner==null?new ProfileSelectionService.Selection(false,"No candidate met chronological sample requirements",null):selection.apply(winner,scope,scope==ProfileScope.COIN_SPECIFIC?universe.getFirst():null,strategy.code(),strategy.version(),horizon);return new ResearchResult(scope,scope==ProfileScope.COIN_SPECIFIC?universe.getFirst().getSymbol():null,strategy.code(),horizon,from,to,ranked,applied,errors);}
 List<WalkForwardProfileSelector.Observation>observations(Coin coin,StrategyDefinition strategy,String parameters,long horizon,Instant from,Instant to,BarSeries series){List<WalkForwardProfileSelector.Observation>out=new ArrayList<>();int targetIndex=Math.max(WARMUP_BARS,series.getBeginIndex());for(int i=targetIndex;i<=series.getEndIndex();i++){Instant signalAt=series.getBar(i).getEndTime();if(signalAt.isBefore(from))continue;Instant targetAt=signalAt.plusSeconds(horizon);if(targetAt.isAfter(to))break;while(targetIndex<=series.getEndIndex()&&series.getBar(targetIndex).getEndTime().isBefore(targetAt))targetIndex++;if(targetIndex>series.getEndIndex())break;var signal=strategy.evaluateAt(series,parameters,i);if(signal.direction()==Direction.NEUTRAL)continue;BigDecimal entry=new BigDecimal(series.getBar(i).getClosePrice().toString()),exit=new BigDecimal(series.getBar(targetIndex).getClosePrice().toString());out.add(new WalkForwardProfileSelector.Observation(coin.getId(),signalAt,signalAt,targetAt,signal.direction(),entry,exit));i=Math.max(i,targetIndex-1);}return out;}
 public record ResearchResult(ProfileScope scope,String coin,String strategyCode,long horizon,Instant from,Instant to,List<WalkForwardProfileSelector.CandidateEvaluation>candidates,ProfileSelectionService.Selection selection,List<String>errors){}
}
